"""In-place foreach negation (aten::_foreach_neg_) with Triton kernels.

Round 5: round-3 architecture plus a bounded program count.  Block dispatch
costs ~8.7 ns per program on this device, so a single large tensor is tiled by
a small number of programs, each iterating over consecutive tiles instead of
being launched once per tile.

* contiguous tensors sharing a dtype are fused into ONE launch (up to 16 per
  launch) on a 2-D grid ``(tensor index, chunk index)``; the kernel selects the
  tensor with a branch chain on ``program_id(0)``
* homogeneous chunks (all numels equal and divisible by BLOCK) use a mask-free
  kernel that takes only the 16 base pointers - no masks on the vector
  transfers and no per-tensor length arguments on the host path
* heterogeneous chunks fall back to the masked variant with per-tensor lengths
* tensors whose address spans provably overlap are never fused, so aliased list
  elements keep ATen's sequential semantics
* non-contiguous tensors go through a per-tensor strided kernel whose dims are
  collapsed on the host (unit dims dropped, adjacent dims merged)
* complex tensors are negated component-wise through a zero-copy real view
* bool (and complex32) are rejected, an empty list raises like ATen
* nothing is allocated and no framework arithmetic is used
"""

import torch
import triton
import triton.language as tl

_MAX_DIMS = 8
_MAX_BATCH = 16

_ELEMENT_SIZE = {
    torch.float16: 2,
    torch.bfloat16: 2,
    torch.float32: 4,
    torch.float64: 8,
    torch.int8: 1,
    torch.int16: 2,
    torch.int32: 4,
    torch.int64: 8,
    torch.uint8: 1,
    torch.complex64: 8,
    torch.complex128: 16,
}

# Elements per program chosen so that one program touches roughly 32 KiB of
# input (and the same amount of output).
_BLOCK_BY_ITEMSIZE = {1: 32768, 2: 16384, 4: 8192, 8: 4096, 16: 2048}

# Upper bound on the number of launched programs for the flat path.  Each
# program costs ~8.7 ns of block dispatch on this device, so beyond this point
# a program iterates over consecutive blocks instead of being launched anew.
_PROGRAM_TARGET = 2048


@triton.jit
def _neg_flat_loop(x_ptr, rep, BLOCK: tl.constexpr):
    """Mask-free negation of ``rep`` consecutive BLOCK-element tiles."""
    pid = tl.program_id(0)
    base = pid * (BLOCK * rep)
    for i in tl.range(0, rep):
        offs = base + i * BLOCK + tl.arange(0, BLOCK)
        x = tl.load(x_ptr + offs)
        tl.store(x_ptr + offs, -x)


@triton.jit
def _neg_flat_even(x_ptr, BLOCK: tl.constexpr):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    x = tl.load(x_ptr + offs)
    tl.store(x_ptr + offs, -x)


@triton.jit
def _neg_flat(x_ptr, n, BLOCK: tl.constexpr):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    mask = offs < n
    x = tl.load(x_ptr + offs, mask=mask, other=0)
    tl.store(x_ptr + offs, -x, mask=mask)


@triton.jit
def _neg_even_block(ptr, idx):
    x = tl.load(ptr + idx)
    tl.store(ptr + idx, -x)


@triton.jit
def _neg_block(ptr, idx, n):
    mask = idx < n
    x = tl.load(ptr + idx, mask=mask, other=0)
    tl.store(ptr + idx, -x, mask=mask)


