@triton.jit
def _neg_strided(
    x_ptr,
    n,
    u0,
    u1,
    u2,
    u3,
    u4,
    u5,
    u6,
    u7,
    v0,
    v1,
    v2,
    v3,
    v4,
    v5,
    v6,
    v7,
    NDIM: tl.constexpr,
    BLOCK: tl.constexpr,
):
    """Negate ``n`` logical elements of a strided view, innermost dim first."""
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    mask = offs < n

    rem = offs
    off = (rem % u0) * v0
    rem = rem // u0
    if NDIM > 1:
        off = off + (rem % u1) * v1
        rem = rem // u1
    if NDIM > 2:
        off = off + (rem % u2) * v2
        rem = rem // u2
    if NDIM > 3:
        off = off + (rem % u3) * v3
        rem = rem // u3
    if NDIM > 4:
        off = off + (rem % u4) * v4
        rem = rem // u4
    if NDIM > 5:
        off = off + (rem % u5) * v5
        rem = rem // u5
    if NDIM > 6:
        off = off + (rem % u6) * v6
        rem = rem // u6
    if NDIM > 7:
        off = off + (rem % u7) * v7

    x = tl.load(x_ptr + off, mask=mask, other=0)
    tl.store(x_ptr + off, -x, mask=mask)


def _collapse(shape, strides):
    """Minimal (size, stride) description, ordered innermost first.

    Unit dims are dropped and adjacent dims are merged whenever the outer
    stride equals inner_size * inner_stride, which is exactly the memory
    contiguity condition.
    """
    dims = [(sz, st) for sz, st in zip(shape, strides) if sz != 1]
    out = []
    for sz, st in reversed(dims):
        if out and st == out[-1][1] * out[-1][0]:
            inner_sz, inner_st = out[-1]
            out[-1] = (inner_sz * sz, inner_st)
        else:
            out.append((sz, st))
    return out


def _pick_block(n, itemsize):
    block = _BLOCK_BY_ITEMSIZE.get(itemsize, 4096)
    while block > 1024 and block > n:
        block //= 2
    return block


def _pick_rep(chunks):
    """Number of consecutive tiles one program should iterate over."""
    rep = 1
    while rep * 2 * _PROGRAM_TARGET <= chunks and chunks % (rep * 2) == 0:
        rep *= 2
    return rep


def _neg_single(t, n):
    """Negate one contiguous tensor, mask-free when the tiling is exact."""
    block = _pick_block(n, t.element_size())
    if n % block == 0:
        chunks = n // block
        rep = _pick_rep(chunks)
        if rep == 1:
            _neg_flat_even[(chunks,)](t, block)
        else:
            _neg_flat_loop[(chunks // rep,)](t, rep, block)
    else:
        _neg_flat[(triton.cdiv(n, block),)](t, n, block)


def _neg_view(t):
    """Per-tensor launch for a non-contiguous view."""
    n = t.numel()
    block = _pick_block(n, t.element_size())
    dims = _collapse(t.shape, t.stride())
    sizes = [d[0] for d in dims] + [1] * (_MAX_DIMS - len(dims))
    strides = [d[1] for d in dims] + [0] * (_MAX_DIMS - len(dims))
    _neg_strided[(triton.cdiv(n, block),)](t, n, *sizes, *strides, len(dims), block)


def _no_alias(ts):
    """True when no two contiguous tensors in ``ts`` can touch one address.

    For a contiguous tensor the address span is exactly
    ``[data_ptr, data_ptr + numel * itemsize)``, so span disjointness is a
    sufficient condition for a fused launch to preserve sequential semantics.
    """
    if all(t._base is None for t in ts):
        if len({t.data_ptr() for t in ts}) == len(ts):
            return True
    spans = sorted(
        (t.data_ptr(), t.data_ptr() + t.numel() * t.element_size()) for t in ts
    )
    end = -1
    for start, stop in spans:
        if start < end:
            return False
        end = stop
    return True


def _launch_flat(pairs, itemsize):
    count = len(pairs)
    if count == 1:
        _neg_single(pairs[0][0], pairs[0][1])
        return
    if not _no_alias([p[0] for p in pairs]):
        for t, n in pairs:
            _neg_single(t, n)
        return
    for start in range(0, count, _MAX_BATCH):
        chunk = pairs[start : start + _MAX_BATCH]
        lens = [p[1] for p in chunk]
        max_n = max(lens)
        block = _pick_block(max_n, itemsize)
        ptrs = [p[0] for p in chunk]
        pad = _MAX_BATCH - len(chunk)
        if pad:
            ptrs.extend([ptrs[0]] * pad)
        same = max_n == lens[0] and all(x == max_n for x in lens)
        if same and max_n % block == 0:
            _neg_multi_even[(len(chunk), max_n // block)](*ptrs, block)
        else:
            _neg_multi[(len(chunk), triton.cdiv(max_n, block))](
                *ptrs, *lens, *([0] * pad), block
            )


def foreach_neg_(self):
    if not isinstance(self, (list, tuple)):
        raise TypeError("argument 'self' must be tuple of Tensors")
    if len(self) == 0:
        raise RuntimeError("Tensor list must have at least one tensor.")
    groups = {}
    views = []
    for t in self:
        if not isinstance(t, torch.Tensor):
            raise TypeError("argument 'self' must be tuple of Tensors")
        dtype = t.dtype
        if dtype.is_complex:
            if dtype == torch.complex32:
                raise RuntimeError("\"foreach\" not implemented for 'complex32'")
            # Zero-copy real view: negation is component-wise.
            t = torch.view_as_real(t)
            dtype = t.dtype
        elif dtype == torch.bool:
            raise RuntimeError("negation on a bool tensor is not supported")
        if dtype not in _ELEMENT_SIZE:
            raise RuntimeError(
                "\"foreach\" not implemented for '{}'".format(
                    str(dtype).replace("torch.", "")
                )
            )
        n = t.numel()
        if n == 0:
            continue
        if t.is_contiguous():
            bucket = groups.get(dtype)
            if bucket is None:
                groups[dtype] = bucket = []
            bucket.append((t, n))
        else:
            views.append(t)
    for t in views:
        _neg_view(t)
    for dtype, pairs in groups.items():
        _launch_flat(pairs, _ELEMENT_SIZE[dtype])
    return None
